(e/'c19-loop-1-gates.json').write_text(json.dumps(gates,ensure_ascii=False,indent=2)+'\\n')
p={'loop':1,'activation_state':'semantic_evaluator_started','checklist':[{'item':v,'status':'achieved' if i<2 else 'not_achieved','evidence':(['eval-log/run-dev-graph-system-spec/'+('R0-context' if i==0 else 'R1-preflight')+'/audit.json'] if i<2 else ['正規後続操作待ち。seed章を今回の実行証拠としていない'])} for i,v in enumerate(items)],'feedback_criteria':[{'id':'IN1','status':'PASS','iterations':[{'loop':1,'status':'PASS','evidence':'eval-log/c19-loop-1-gates.json'}]},{'id':'OUT1','status':'external_pending'}],'merged_directive_for_next':next_step}
(e/'run-dev-graph-system-spec-progress.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\\n')
row={'original_goal':g,'original_goal_hash':h,'current_goal_snapshot':'R0/R1独立監査PASS、3正規gate exit0。正規依存flowは未実行。','delta_from_original':'なし。preflightのみ完了。','merged_directive_for_next':next_step,'drift_signal':False,'loop':1,'IN1':gates}
f=e/'run-dev-graph-system-spec-intermediate.jsonl'
with f.open('a') as stream: stream.write(json.dumps(row,ensure_ascii=False)+'\\n')
required={'original_goal','original_goal_hash','current_goal_snapshot','delta_from_original','merged_directive_for_next','drift_signal'}
for line in f.read_text().splitlines():
 x=json.loads(line); assert required<=x.keys() and x['original_goal']==g and x['original_goal_hash']==h
operation={'kind':'native-operation','state':'waiting_operation','operation_id':'system-spec-elicit','target_skill':'system-spec-harness:run-system-spec-elicit','args':'--spec-state /private/tmp/harness-codex-ci4-20261102/cases/system-spec/fx/system-spec/spec-state.json --resume'}
(r/'native-operation-request.json').write_text(json.dumps(operation,ensure_ascii=False,indent=2)+'\\n')
print('周回1の集約・goal/hash検査PASS。native-operation-request.json保存済み。')
PY"

